<?php require_once 'db_connect.php'; $id=trim($_GET['id']??$_POST['id']??'');if($id==='')die('Invalid student ID');$s=$conn->prepare('SELECT first_name,last_name FROM students WHERE id=?');$s->bind_param('s',$id);$s->execute();$r=$s->get_result()->fetch_assoc(); if(!$r)die('Student not found');if($_SERVER['REQUEST_METHOD']==='POST'){$d=$conn->prepare('DELETE FROM students WHERE id=?');$d->bind_param('s',$id);$d->execute();$ok=$d->affected_rows===1; echo $ok?'<p class="success">Student deleted successfully.</p>':'<p>Failed to delete student.</p>';echo '<a href="index.php">Back to list</a>';exit;}?><!doctype html><html><head><title>Delete Student</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h2>Confirm Delete</h2><p>Are you sure you want to delete <strong><?=htmlspecialchars($r['first_name'].' '.$r['last_name'])?></strong>?</p><form method="POST"><input type="hidden" name="id" value="<?=htmlspecialchars($id)?>"><button class="btn danger">Yes, Delete</button> <a class="btn" href="index.php">Cancel</a></form></div></body></html>